"""Shared staff + multi-operation UI edits mirrored from the desktop prototype.

Fail closed if a baseline changes. Do not overwrite or re-key any save records.
"""
def _apply(source: str, edits, title: str) -> str:
    for i, (old, new) in enumerate(edits):
        count = source.count(old)
        if count != 1:
            raise AssertionError(f"{title} anchor {i}: {count} matches; refusing unsafe update")
        source = source.replace(old, new, 1)
    return source

